import { mapState } from "vuex";
// import theme from "@/mixins/theme";
export default {
  name: "banner", // 组件名称
  cname: "轮播图", // 标题名称
  icon: "#iconzujian-lunbotu",
  defaultName: "swiperBg", // 外面匹配名称
  configName: "c_banner", // 右侧配置名称
  type: 0, // 0 基础组件 1 营销组件 2工具组件
  props: {
    index: {
      type: null,
    },
    num: {
      type: null,
    },
	colorStyle:{
		type: null
	}
  },
  computed: {
    ...mapState("admin/mobildConfig", ["defaultArray"]),
  },
  watch: {
    pageData: {
      handler(nVal, oVal) {
        this.setConfig(nVal);
      },
      deep: true,
    },
    num: {
      handler(nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[nVal];
        this.setConfig(data);
      },
      deep: true,
    },
    defaultArray: {
      handler(nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[this.num];
        this.setConfig(data);
      },
      deep: true,
    },
  },
  // mixins: [theme],
  data() {
    return {
      // 默认初始化数据禁止修改
      defaultConfig: {
		cname: "轮播图",
        name: "swiperBg",
        timestamp: this.num,
		isHide:false,
        setUp: {
          tabVal: 0
        },
		titleLeft:'展示设置',
		titleContent:'内容设置',
		titleRight:'指示器设置',
		titleImg:'图片设置',
		titleCurrency:'通用样式',
		styleConfig:{
			title: '选择风格',
			tabVal: 1,
			tabList: [
				{
				  name: '样式一'
				},
			    {
			      name: '样式二'
			    },
				{
				  name: '样式三'
				}
			]
		},
        // 图片列表
        swiperConfig: {
          maxList: 10,
          list: [
            {
              img: "",
			  imgTitle:'图一',
              info: [
                {
                  title: "链接",
                  value: "",
                  tips: "请输入链接",
                  max: 100,
                },
              ],
            },
          ],
        },
		docConfig:{
			title: '指示器样式',
			tabVal: 0,
			tabList: [
				{
				  name: '样式一'
				},
			    {
			      name: '样式二'
			    },
				{
				  name: '样式三'
				},
				{
				  name: '样式四'
				}
			]
		},
		docPosition:{
			title: '指示器位置',
			tabVal: 1,
			tabList: [
				{
				  name: '左对齐'
				},
			    {
			      name: '居中对齐'
			    },
				{
				  name: '右对齐'
				}
			]
		},
		toneConfig:{
			title: '色调',
			tabVal: 0,
			tabList: [
				{
				  name: '跟随主题风格'
				},
			    {
			      name: '自定义'
			    }
			]
		},
		dotColor: {
		  title: "选中样式",
		  default: [
		    {
		      item: "#E93323",
		    },
		  ],
		  color: [
		    {
		      item: "#E93323",
		    },
		  ],
		},
		dotBgColor:{
			title: "常规样式",
			default: [
			  {
			    item: "#DDDDDD",
			  },
			],
			color: [
			  {
			    item: "#DDDDDD",
			  },
			],
		},
		filletImg:{
			title:'图片圆角',
			type: 0,
			list: [
			  {
				val: "全部",
				icon: "iconcaozuo-zhengti",
			  },
			  {
				val: "单个",
				icon: "iconcaozuo-bianjiao",
			  }
			],
			valName:'圆角值',
			val: 10,
			min: 0,
			valList:[
				{val:0},
				{val:0},
				{val:0},
				{val:0}
			]
		},
		imgConfig:{
			title: "图片间距",
			val: 10,
			min: 0
		},
        bgColor: {
          title: "底部背景",
          default: [
            {
              item: "#F62C2C",
            }
          ],
          color: [
            {
              item: "#F62C2C",
            }
          ],
        },
		topConfig:{
			title: '上边距',
			val: 10,
			min: 0
		},
		bottomConfig:{
			title: '下边距',
			val: 10,
			min: 0
		},
        // 左右间距
        prConfig: {
          title: "左右边距",
          val: 10,
          min: 0,
        },
        // 页面间距
        mbConfig: {
          title: "页面上间距",
          val: 0,
          min: 0,
        },
        txtStyle: {
          title: '指示器位置',
          type: 0,
          list: [
            {
              val: '居左',
              icon:'icondoc_left'
            },
            {
              val: '居中',
              icon:'icondoc_center'
            },
            {
              val: '居右',
              icon:'icondoc_right'
            }
          ]
        }
      },
	  styleConfig:0,
	  prConfig: 0,
	  topConfig:0,
	  bottomConfig:0,
	  bgColor: '',
	  filletImg:0,
	  filletValImg:0,
	  valListImg:[],
	  mTOP: 0,
	  docPosition:0,
	  toneConfig:0,
	  dotBgColor:'',
	  dotColor: "",
	  imgConfig: 0,
      pageData: {},
      edge: 0,
      imgSrc: [],
      docStyle: 0
    };
  },
  mounted() {
    this.$nextTick(() => {
      this.pageData = this.$store.state.admin.mobildConfig.defaultArray[
        this.num
      ];
      this.setConfig(this.pageData);
    });
  },
  methods: {
    setConfig(data) {
      if (!data) return;
      if(data.mbConfig){
		this.styleConfig = data.styleConfig.tabVal;
		this.prConfig = data.prConfig.val;
		this.topConfig = data.topConfig.val;
		this.bottomConfig = data.bottomConfig.val;
		this.bgColor = data.bgColor.color[0].item;
		this.filletImg = data.filletImg.type;
		this.filletValImg = data.filletImg.val;
		this.valListImg = data.filletImg.valList;
		this.mTOP = data.mbConfig.val;
		this.docPosition = data.docPosition.tabVal;
		this.toneConfig = data.toneConfig.tabVal;
		this.dotColor = data.dotColor.color[0].item;
		this.dotBgColor = data.dotBgColor.color[0].item;
        this.imgConfig = data.imgConfig.val;
        this.imgSrc = data.swiperConfig.list;
        this.docStyle = data.docConfig.tabVal;
      }
    },
  },
};
